preConditionHook:
// HOW BIG IS THE PATTERN? The bar count from the FIRST push to the current bar
// must lie inside [minBars, maxBars]. This is the book's size test, and one
// rule carries all three of its parameterizations rather than three rules: a
// wedge FLAG runs 10-20 bars (R18-04 = V05-07, the default here), a wedge
// REVERSAL 20 or more (R18-05 = V05-06 -- set maxBars to 0, which means
// unbounded), and a three-legged pullback 5-15 (R11-12).
//
// R18-05 / V05-06 also demand a clear trend channel line. That half has no
// numeric definition anywhere in the bucket and is left to the
// trend-channel-line fit rule in lines_channels_channels; recorded here, not
// encoded.
//
// MIRRORED, not identical on both sides, though the merged slice recorded the
// rule as same-sided: the first push of a three-push BOTTOM is a swing low and
// the first push of a three-push TOP is a swing high, so the long pane must
// read loBarP and the short hiBarP. The arithmetic is the same on both sides;
// the pivot series is not.
//
// The pivot's BARS-AGO count IS the bar distance from the current bar, so the
// pattern's length needs no bar-number bookkeeping. pushCount selects which
// pivot counts as the first push and is clamped to the three the scan keeps.
// The bar counts and the mode selectors are integers, compared exactly rather
// than through el_*; only prices carry the relational tolerance.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the oldest push is found by hand. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the swingStrength
// NEWER bars -- bars-ago indexing, so the newer bars are the smaller k and
// take el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength bars; candidate offsets swingStrength .. lookbackBars - 1, the
// neighbourhood reaching swingStrength bars past the window, so the deepest
// bar touched is lookbackBars - 1 + swingStrength. lookbackBars must exceed
// maxBars or the window can never be satisfied. No early break, as the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
loBound = (int)minBars;
hiBound = (int)maxBars;
nHiPiv = 0;
nLoPiv = 0;
hiBar1 = -1;
hiBar2 = -1;
hiBar3 = -1;
loBar1 = -1;
loBar2 = -1;
loBar3 = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiBar1 = j;
        if (nHiPiv == 2) hiBar2 = j;
        if (nHiPiv == 3) hiBar3 = j;
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loBar1 = j;
        if (nLoPiv == 2) loBar2 = j;
        if (nLoPiv == 3) loBar3 = j;
    }
}
needP = (int)pushCount;
if (needP < 1) needP = 1;
if (needP > 3) needP = 3;
hiBarP = hiBar3;
loBarP = loBar3;
if (needP == 1) { hiBarP = hiBar1; loBarP = loBar1; }
if (needP == 2) { hiBarP = hiBar2; loBarP = loBar2; }
inWindowLo = (nLoPiv >= needP) && (loBarP >= loBound) && ((hiBound == 0) || (loBarP <= hiBound));
inWindowHi = (nHiPiv >= needP) && (hiBarP >= loBound) && ((hiBound == 0) || (hiBarP <= hiBound));
